package com.desktodo.app;
import android.app.*;import android.os.*;import org.json.*;import java.io.*;import java.time.*;import java.util.concurrent.CancellationException;
/** Isolated fixtures only: does not edit live tasks, settings or screen. */
public final class AssistantChecks extends Instrumentation {
 Bundle args;int count;
 @Override public void onCreate(Bundle b){args=b;start();}
 void check(boolean b,String why){count++;if(!b)throw new AssertionError(why);}
 interface Attempt{void run()throws Exception;}
 void reject(Attempt action,String why)throws Exception{boolean rejected=false;try{action.run();}catch(Exception e){rejected=true;}check(rejected,why);}
 JSONObject call(String name,JSONObject arguments)throws Exception{return new JSONObject().put("content",JSONObject.NULL).put("tool_calls",new JSONArray().put(new JSONObject().put("id","call-1").put("type","function").put("function",new JSONObject().put("name",name).put("arguments",arguments.toString()))));}
 @Override public void onStart(){Bundle result=new Bundle();File file=new File(getTargetContext().getCacheDir(),"assistant-checks.json");try{
  JSONObject context=new JSONObject().put("tasks",new JSONArray().put(DeskModel.task("fixture",null))).put("settings",DeskModel.defaults()).put("memories",new JSONArray());AgentTools tools=new AgentTools(context,"test request");
  JSONObject add=new JSONObject().put("operation","add").put("title","new fixture").put("due","2026-10-19T07:00:00Z");tools.execute("propose_task_change",add);check(tools.proposals.length()==1&&context.getJSONArray("tasks").length()==1,"proposal has no write side effect");tools.execute("propose_task_change",add);check(tools.proposals.length()==1,"deduplicate identical proposal");
  TaskProposal.Result applied=TaskProposal.apply(context.getJSONArray("tasks"),new JSONArray(),tools.proposals.getJSONObject(0));check(applied.tasks.length()==2&&context.getJSONArray("tasks").length()==1,"confirmation applies isolated transaction");reject(()->TaskProposal.apply(applied.tasks,applied.history,tools.proposals.getJSONObject(0)),"same add cannot replay");
  AgentTools completion=new AgentTools(context,"complete");completion.execute("propose_task_change",new JSONObject().put("operation","complete").put("id",context.getJSONArray("tasks").getJSONObject(0).getString("id")));JSONObject proposal=completion.proposals.getJSONObject(0);TaskProposal.Result removed=TaskProposal.apply(context.getJSONArray("tasks"),new JSONArray(),proposal);check(removed.tasks.length()==0&&removed.history.getJSONObject(0).optString("recordType").equals("completed"),"complete removes and records");JSONArray changed=DeskModel.copy(context.getJSONArray("tasks"));changed.getJSONObject(0).put("title","changed");reject(()->TaskProposal.apply(changed,new JSONArray(),proposal),"stale card rejected");
  reject(()->tools.execute("shell",new JSONObject()),"unknown tool rejected");reject(()->tools.execute("get_time",new JSONObject().put("command","bad")),"unknown argument rejected");reject(()->tools.execute("propose_layout",new JSONObject().put("layout","custom").put("ratio",90)),"layout bounds");reject(()->tools.execute("propose_task_change",new JSONObject().put("operation","add").put("title","bad").put("due","tomorrow")),"ambiguous due rejected");reject(()->tools.execute("propose_task_change",new JSONObject().put("operation","complete").put("id","missing")),"fabricated ID rejected");
  JSONArray memory=PreferenceMemory.save(new JSONArray(),null,"出门","下雨带伞","fixture");String id=memory.getJSONObject(0).getString("id");check(PreferenceMemory.enabled(memory).length()==1,"memory visible");memory=PreferenceMemory.set(memory,id,"enabled",false);check(PreferenceMemory.enabled(memory).length()==0,"disabled memory excluded");memory=PreferenceMemory.set(memory,id,"deleted",true);check(PreferenceMemory.enabled(memory).length()==0,"deleted memory excluded");memory=PreferenceMemory.set(memory,id,"deleted",false);check(!memory.getJSONObject(0).optBoolean("deleted"),"soft delete restored");final JSONArray m=memory;reject(()->PreferenceMemory.save(m,null,"出门","duplicate","test"),"duplicate memory rejected");
  file.delete();new File(file+".bak").delete();AgentStore store=new AgentStore(file);store.message("user","fixture");store.memories=memory;store.append(tools.proposals);store.proposals.getJSONObject(0).put("status","applying");store.save();AgentStore loaded=new AgentStore(file);loaded.recoverApplying();check(loaded.messages.length()==1&&loaded.memories.length()==1&&loaded.proposals.getJSONObject(0).getString("status").equals("interrupted"),"atomic recovery never silently repeats applying");
  AgentTools loopTools=new AgentTools(context,"query");final int[] calls={0};AgentRunner.Provider provider=(messages,schemas,deadline,stop)->{if(calls[0]++==0)return call("propose_task_change",add);check(messages.getJSONObject(messages.length()-1).getString("role").equals("tool"),"tool result returned to provider");return new JSONObject().put("content","请确认卡片");};AgentRunner.Result run=AgentRunner.run("query",new JSONArray(),loopTools,provider,s->{},new AgentRunner.Stop(),SystemClock.elapsedRealtime()+10000);check(run.proposals.length()==1&&run.trace.length()==1&&context.getJSONArray("tasks").length()==1,"bounded tool round trip without writes");
  reject(()->AgentRunner.run("query",new JSONArray(),new AgentTools(context,"q"),(messages,schemas,deadline,stop)->call("get_time",new JSONObject()),s->{},new AgentRunner.Stop(),SystemClock.elapsedRealtime()+10000),"repeated no-progress tool loop stops");AgentRunner.Stop stopped=new AgentRunner.Stop();stopped.cancel();reject(()->AgentRunner.run("query",new JSONArray(),new AgentTools(context,"q"),provider,s->{},stopped,SystemClock.elapsedRealtime()+10000),"cancellation prevents provider call");reject(()->AgentRunner.run("query",new JSONArray(),new AgentTools(context,"q"),provider,s->{},new AgentRunner.Stop(),SystemClock.elapsedRealtime()-1),"deadline respected");
  long due=Instant.parse("2026-10-19T07:00:00Z").toEpochMilli();check(ReminderPolicy.next(due,due-3600000,true,false,22,8)==due-600000,"10 minute early reminder");check(ReminderPolicy.next(due,due,true,false,22,8)<0,"no late early reminder");check(ReminderPolicy.next(due,due+86400001,false,false,22,8)<0,"catchup limited 24h");long night=Instant.parse("2026-10-19T15:00:00Z").toEpochMilli(),morning=Instant.parse("2026-10-20T00:00:00Z").toEpochMilli();check(ReminderPolicy.next(night,night-10000,false,true,22,8)==morning,"cross midnight quiet defers due");check(ReminderPolicy.next(night,night-3600000,true,true,22,8)<0,"early reminder deferred beyond due skipped");check(ReminderPolicy.next(due,due-3600000,false,true,15,15)==due,"equal quiet bounds disable interval");
  JSONObject reminders=new JSONObject().put("enabled",true).put("quietEnabled",false);JSONArray scheduledTasks=new JSONArray().put(DeskModel.task("alarm fixture",Instant.ofEpochMilli(due).toString()));JSONObject plan=ReminderPlan.build(scheduledTasks,reminders,due-3600000,java.util.Collections.emptySet());check(plan.length()==2,"two deadline stages planned");java.util.Set<String> sent=new java.util.HashSet<>();for(java.util.Iterator<String> it=plan.keys();it.hasNext();)sent.add(it.next());check(ReminderPlan.build(scheduledTasks,reminders,due-3600000,sent).length()==0,"restart ledger prevents duplicate alarms");check(ReminderPlan.build(new JSONArray(),reminders,due-3600000,java.util.Collections.emptySet()).length()==0,"complete/delete removes every scheduled alarm");scheduledTasks.getJSONObject(0).put("due",Instant.ofEpochMilli(due+3600000).toString());check(ReminderPlan.build(scheduledTasks,reminders,due-3600000,sent).length()==2,"changed deadline gets new alarm keys");check(ReminderPlan.build(scheduledTasks,DeskModel.copy(reminders).put("enabled",false),due-3600000,sent).length()==0,"disabled reminders have no plan");
  if(args!=null&&"1".equals(args.getString("importKey"))){File secret=new File(getTargetContext().getFilesDir(),"agent-key-import.txt");try{String key=MainActivity.read(secret).trim();AgentVault.put(getTargetContext(),key);check(AgentVault.get(getTargetContext()).equals(key),"keystore round trip");check(!getTargetContext().getSharedPreferences("mojian-agent-vault",0).getString("key","").contains(key),"key ciphertext differs from plaintext");}finally{if(secret.exists()&&!secret.delete())throw new Exception("private key import cleanup failed");}}
  if(args!=null&&"1".equals(args.getString("live"))){String key=AgentVault.get(getTargetContext());check(!key.isEmpty(),"configured live credential");String model=getTargetContext().getSharedPreferences("mojian-native",0).getString("agent-model","deepseek-flash");AgentRunner.Result live=AgentRunner.run("请使用 get_time 工具读取当前时间，再简洁告诉我几点。不做任何修改。",new JSONArray(),new AgentTools(context,"read time"),AgentRunner.deepSeek(key,model),s->{},new AgentRunner.Stop(),SystemClock.elapsedRealtime()+120000);check(!live.answer.isEmpty()&&live.trace.length()>0&&live.proposals.length()==0,"live DeepSeek tool round trip");}
  result.putString("stream","PASS: "+count+" assistant checks (proposals, confirmation, stale/replay guards, memory, atomic recovery, tool loop, cancellation, quiet hours; live only when requested)\n");finish(Activity.RESULT_OK,result);
 }catch(Throwable e){result.putString("stream","FAIL: "+e.toString()+"\n");finish(Activity.RESULT_CANCELED,result);}finally{file.delete();new File(file+".bak").delete();}}
}
